const input = $input.first().json;

const vendorData = $('Code - Normalize Vendor Data').first().json;

const vendorUrl = vendorData.vendor_url;

if (!vendorUrl) {
  throw new Error('vendor_url is missing');
}

const hrefs = input.href;

if (!Array.isArray(hrefs)) {
  throw new Error('HTML Extract did not return an href array');
}

const output = [];

for (const href of hrefs) {

  if (!href || typeof href !== 'string') {
    continue;
  }

  const value = href.trim();

  // Ignore anchors.
  if (value.startsWith('#')) {
    continue;
  }

  // Ignore email links.
  if (
    value.startsWith('mailto:') ||
    value.startsWith('tel:') ||
    value.startsWith('javascript:')
  ) {
    continue;
  }

  let url;

  // Absolute URL
  if (/^https?:\/\//i.test(value)) {
    url = value;
  }

  // Root-relative URL
  else if (value.startsWith('/')) {
    url = vendorUrl + value;
  }

  // Relative URL
  else {
    url = vendorUrl + '/' + value;
  }

  output.push({
    json: {
      url: url
    }
  });
}

return output;

// const input = $input.first().json;
const input = $json.body || $json;

const rawUrl = input["Vendor Website"];

if (!rawUrl || typeof rawUrl !== "string") {
  throw new Error("Vendor Website is required.");
}

let vendorUrl = rawUrl.trim();

// Remove whitespace accidentally included in the URL.
vendorUrl = vendorUrl.replace(/\s+/g, "");

// Add HTTPS if the user entered only a domain.
if (!/^https?:\/\//i.test(vendorUrl)) {
  vendorUrl = `https://${vendorUrl}`;
}

// Validate basic HTTP/HTTPS URL structure.
const urlPattern = /^https?:\/\/[^\/\s]+(?:\/[^\s]*)?$/i;

if (!urlPattern.test(vendorUrl)) {
  throw new Error(`Invalid Vendor Website: ${rawUrl}`);
}

// Remove query string and fragment.
vendorUrl = vendorUrl.split("?")[0].split("#")[0];

// Remove trailing slash.
vendorUrl = vendorUrl.replace(/\/+$/, "");

// Extract hostname.
const hostnameMatch = vendorUrl.match(/^https?:\/\/([^\/]+)/i);

if (!hostnameMatch) {
  throw new Error(`Could not determine vendor domain: ${rawUrl}`);
}

const vendorDomain = hostnameMatch[1]
  .toLowerCase()
  .replace(/^www\./, "");

// Convert all top-level keys in the input object to snake_case
const toSnakeCase = (str) =>
  str
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
    .replace(/[\s\W]+/g, "_")
    .toLowerCase();

const snakeCasedInput = Object.fromEntries(
  Object.entries(input).map(([key, value]) => [toSnakeCase(key), value])
);

return [
  {
    json: {
      ...snakeCasedInput,
      vendor_url: vendorUrl,
      vendor_domain: vendorDomain
    }
  }
];

const seen = new Set();
const output = [];

for (const item of $input.all()) {
  const url = item.json.url;

  if (!url) {
    continue;
  }

  const key = url.toLowerCase();

  if (seen.has(key)) {
    continue;
  }

  seen.add(key);

  output.push({
    json: {
      url
    }
  });
}

return output;

const results = [];

for (const item of $input.all()) {
  // Extract raw string output from the AI response
  let rawOutput = item.json.output ?? item.json.text ?? item.json;

  if (typeof rawOutput !== 'string') {
    rawOutput = JSON.stringify(rawOutput);
  }

  // Clean markdown code blocks (e.g. ```json ... ```) and non-breaking space characters
  const cleanString = rawOutput
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .replace(/\u00A0/g, ' ')
    .trim();

  try {
    const parsed = JSON.parse(cleanString);

    // Extract array from parsed.data (or handle top-level arrays)
    const itemsList = Array.isArray(parsed)
      ? parsed
      : (Array.isArray(parsed.data) ? parsed.data : [parsed]);

    // Push each item as an independent n8n JSON object
    for (const record of itemsList) {
      results.push({ json: record });
    }
  } catch (error) {
    // Fallback error item if JSON parsing fails
    results.push({
      json: {
        error: 'Failed to parse AI JSON output',
        errorMessage: error.message,
        rawOutput: rawOutput
      }
    });
  }
}

return results;

const responses = $input.all();
const requests = $('Filter').all();
const vendor = $('Code - Normalize Vendor Data').first().json;

function decodeEntities(value) {
  return String(value || '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

function cleanHtml(value) {
  const text = String(value || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<[^>]+>/g, ' ');

  return decodeEntities(text)
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 7000);
}

function getBody(json) {
  if (typeof json === 'string') return json;
  if (typeof json?.data === 'string') return json.data;
  if (typeof json?.body === 'string') return json.body;
  if (typeof json?.response === 'string') return json.response;

  return '';
}

const output = [];

for (const responseItem of responses) {

  const response = responseItem.json || {};

  // Get the original item index from n8n's item pairing
  const pairedItem = responseItem.pairedItem;

  let requestIndex;

  if (Array.isArray(pairedItem)) {
    requestIndex = pairedItem[0]?.item;
  } else {
    requestIndex = pairedItem?.item;
  }

  const request = requests[requestIndex]?.json || {};

  const body = getBody(response);
  const text = cleanHtml(body);

  output.push({
    json: {
      vendor_name: vendor.vendor_name || '',
      vendor_website: vendor.vendor_website || '',
      page_type: request.category || '',
      url: request.url || '',
      text_excerpt: text
    }
  });
}

return output;

const evidence = $('Code - Normalize Vendor Data').first().json;

const raw = String(
  $json.output ||
  $json.text ||
  $json.response ||
  ''
).trim();

const cleaned = raw
  .replace(/^```(?:json)?/i, '')
  .replace(/```$/i, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(`AI did not return valid JSON: ${error.message}`);
}


// --------------------------------------------------
// AI schema defaults
// --------------------------------------------------

const schemaDefaults = {
  summary: 'Unknown',

  // New AI field
  assurance_score: 0,

  risk_level: 'Critical',

  gdpr: false,
  soc2: false,
  iso27001: false,
  hipaa: false,

  sso_supported: false,
  mfa_supported: false,
  encryption_mentioned: false,

  // Kept for compatibility with the existing workflow.
  // AI may now interpret this as a compliance portal / trust center.
  trust_center: false,

  privacy_policy_found: false,

  data_storage_locations: ['Unknown'],
  subprocessors: ['Unknown'],

  potential_risks: ['Unknown'],
  recommended_actions: ['Manual security review required']
};


// --------------------------------------------------
// Merge AI response with defaults
// --------------------------------------------------

const result = {
  ...schemaDefaults,
  ...parsed
};


// --------------------------------------------------
// Normalize boolean fields
// --------------------------------------------------

const booleanFields = [
  'gdpr',
  'soc2',
  'iso27001',
  'hipaa',
  'sso_supported',
  'mfa_supported',
  'encryption_mentioned',
  'trust_center',
  'privacy_policy_found'
];

for (const key of booleanFields) {
  result[key] = result[key] === true;
}


// --------------------------------------------------
// Normalize assurance score
// --------------------------------------------------

let assuranceScore = Number(result.assurance_score);

if (!Number.isFinite(assuranceScore)) {
  assuranceScore = 0;
}

assuranceScore = Math.max(
  0,
  Math.min(100, Math.round(assuranceScore))
);

result.assurance_score = assuranceScore;


// --------------------------------------------------
// Derive risk score
//
// Existing workflow uses risk_score.
// New AI output uses assurance_score.
//
// Higher assurance = lower risk.
// --------------------------------------------------

const riskScore = 100 - assuranceScore;


// --------------------------------------------------
// Normalize risk level
// --------------------------------------------------

const validRiskLevels = [
  'Low',
  'Medium',
  'High',
  'Critical'
];

if (!validRiskLevels.includes(result.risk_level)) {
  result.risk_level =
    assuranceScore >= 80
      ? 'Low'
      : assuranceScore >= 50
        ? 'Medium'
        : assuranceScore >= 20
          ? 'High'
          : 'Critical';
}


// --------------------------------------------------
// Normalize arrays
// --------------------------------------------------

const arrayFields = [
  'data_storage_locations',
  'subprocessors',
  'potential_risks',
  'recommended_actions'
];

for (const key of arrayFields) {

  if (!Array.isArray(result[key]) || result[key].length === 0) {

    result[key] =
      key === 'recommended_actions'
        ? ['Manual security review required']
        : ['Unknown'];
  }
}


// --------------------------------------------------
// Certifications
// --------------------------------------------------

const certifications = [];

if (result.soc2) {
  certifications.push('SOC 2');
}

if (result.iso27001) {
  certifications.push('ISO 27001');
}

if (result.hipaa) {
  certifications.push('HIPAA');
}


// --------------------------------------------------
// Build Probo description
// --------------------------------------------------

const description = [
  `Requester: ${evidence.requester_name || 'Unknown'} ${evidence.requester_email || 'Unknown'}`,

  `Department: ${evidence.department || 'Unknown'}`,

  `Business justification: ${
    evidence.business_justification || 'Unknown'
  }`,

  `AI summary: ${result.summary || 'Unknown'}`,

  `Assurance score: ${result.assurance_score}/100`,

  `Risk score: ${riskScore}/100`,

  `Risk level: ${result.risk_level}`,

  `GDPR evidence: ${result.gdpr ? 'Yes' : 'No'}`,

  `SOC 2 evidence: ${result.soc2 ? 'Yes' : 'No'}`,

  `ISO 27001 evidence: ${result.iso27001 ? 'Yes' : 'No'}`,

  `HIPAA evidence: ${result.hipaa ? 'Yes' : 'No'}`,

  `SSO supported: ${result.sso_supported ? 'Yes' : 'No'}`,

  `MFA supported: ${result.mfa_supported ? 'Yes' : 'No'}`,

  `Encryption mentioned: ${
    result.encryption_mentioned ? 'Yes' : 'No'
  }`,

  `Trust center / compliance portal: ${
    result.trust_center ? 'Found' : 'Not found'
  }`,

  `Privacy policy: ${
    result.privacy_policy_found ? 'Found' : 'Not found'
  }`,

  `Data storage locations: ${
    result.data_storage_locations.join(', ')
  }`,

  `Subprocessors: ${
    result.subprocessors.join(', ')
  }`,

  `Potential risks: ${
    result.potential_risks.join('; ')
  }`,

  `Recommended actions: ${
    result.recommended_actions.join('; ')
  }`
].join('\n');


const filterItems = $('Filter').all();

const filterLinks = {
  terms_of_service_url: null,
  privacy_document_url: null,
  service_level_agreement_url: null,
  data_processing_agreement_url: null,
  security_page_url: null,
  trust_page_url: null
};

for (const item of filterItems) {
  const { url, category } = item.json;

  if (!url || !category) {
    continue;
  }

  switch (category) {
    case 'terms':
      filterLinks.terms_of_service_url = url;
      break;

    case 'privacy_policy':
      filterLinks.privacy_document_url = url;
      break;

    case 'security':
      filterLinks.security_page_url = url;
      break;

    case 'trust_center':
    case 'compliance':
      filterLinks.trust_page_url = url;
      break;

    case 'dpa':
    case 'data_processing':
      filterLinks.data_processing_agreement_url = url;
      break;
  }

  // No dedicated SLA category, so detect it from the URL.
  if (
    /sla|service-level-agreement|service-level/i.test(url)
  ) {
    filterLinks.service_level_agreement_url = url;
  }
}


// --------------------------------------------------
// Final output
// --------------------------------------------------

return [
  {
    json: {
      // Full normalized AI assessment
      ai: result,

      // Preserve existing downstream fields
      risk_score: riskScore,
      risk_level: result.risk_level,

      // New explicit field available downstream
      assurance_score: assuranceScore,

      certifications: certifications.join(', '),

      probo_description: description,

      // Discovered vendor documents
      filterLinks
    }
  }
];
